/* ---------- Kanban ---------- */
.kbx{width:100%;overflow-x:auto}
.kbx-cols{display:grid;grid-template-columns:repeat(3,minmax(200px,1fr));gap:12px;min-width:640px}
.kbx-c{display:flex;flex-direction:column;gap:8px;padding:10px;border-radius:16px;background:color-mix(in srgb,var(--fg) 5%,transparent);transition:background .25s,box-shadow .25s;min-height:280px}
.kbx-c.over{background:var(--sel);box-shadow:inset 0 0 0 1.5px color-mix(in srgb,var(--accent-mark,var(--accent)) 40%,transparent)}
.kbx-ch{display:flex;align-items:center;gap:8px;padding:2px 4px 4px;font-size:13px}
.kbx-ch b{font-weight:500}
.kbx-ch .n{font-size:12px;color:var(--muted)}
.kbx-ch .ib{margin-left:auto;width:24px;height:24px}
.kbx-list{display:flex;flex-direction:column;gap:8px;flex:1}
.kbx-k{padding:11px 12px;border-radius:13px;background:var(--surface);box-shadow:var(--shadow);display:flex;flex-direction:column;gap:8px;cursor:grab;transition:box-shadow .25s,transform .3s var(--ease),opacity .2s;touch-action:none;user-select:none}
.kbx-k:hover{box-shadow:var(--shadow-pop)}
.kbx-k.drag{opacity:.35}
.kbx-k.ghost{position:fixed;z-index:100;pointer-events:none;transform:rotate(2.5deg) scale(1.03);box-shadow:var(--shadow-pop);cursor:grabbing}
.kbx-k .t{font-size:13px;line-height:1.4}
.kbx-k .f{display:flex;align-items:center;gap:6px}
.kbx-k .f .av{width:20px;height:20px;font-size:9px;margin-left:auto}
.kbx-k .f .think{color:var(--accent-fg,var(--accent))}
.kbx-k.agent{box-shadow:0 0 0 1.5px var(--accent-mark,var(--accent)),var(--shadow)}
.kbx-ph{border-radius:13px;background:color-mix(in srgb,var(--accent) 8%,transparent);border:1.5px dashed color-mix(in srgb,var(--accent-mark,var(--accent)) 50%,transparent)}
.kbx-pr{height:3px;border-radius:2px;background:var(--line);overflow:hidden}
.kbx-pr i{display:block;height:100%;background:var(--accent-mark,var(--accent));width:0;transition:width .3s linear}

DM.def('kanban', (r, c) => {
  const COLS = [['todo','To do'],['doing','In progress'],['done','Done']];
  let K = [
    { id:1, c:'todo', t:'Audit checkout for contrast', tag:['b','Design'], who:['DA','var(--pb)'] },
    { id:2, c:'todo', t:'Write release notes for pricing', tag:['l','Copy'], who:['MK','var(--pl)'] },
    { id:3, c:'todo', t:'Rename layers in Hero', tag:['b','Design'], who:['DA','var(--pb)'] },
    { id:4, c:'doing', t:'Export tokens to CSS', tag:['m','Code'], who:['DA','var(--pb)'], run:.4 },
    { id:5, c:'doing', t:'Review annual plan copy', tag:['l','Copy'], who:['JO','var(--pm)'] },
    { id:6, c:'done', t:'One CTA per pricing card', tag:['b','Design'], who:['MK','var(--pl)'] }
  ];
  // the agent's timer repaints the board, so it waits while a card is dragged or a new title is typed
  const wrap = $('.kbx-cols', r); let dragging = false, editing = false;
  wrap.innerHTML = COLS.map(cl => `<div class="kbx-c" data-c="${cl[0]}"><div class="kbx-ch"><b>${cl[1]}</b><span class="n num"></span><button class="ib" aria-label="Add card" data-tip="Add card">${I('plus','xs')}</button></div><div class="kbx-list"></div></div>`).join('');
  const card = k => `<div class="kbx-k${k.run != null ? ' agent' : ''}" data-id="${k.id}"><span class="t">${k.t}</span>${k.run != null ? `<div class="kbx-pr"><i style="width:${k.run * 100}%"></i></div>` : ''}<span class="f"><span class="tag ${k.tag[0]}">${k.tag[1]}</span>${k.run != null ? '<span class="think on"><i></i><i></i><i></i><i></i></span>' : ''}${AV(k.who[0], k.who[1])}</span></div>`;
  function paint(){ COLS.forEach(cl => { const col = $(`.kbx-c[data-c="${cl[0]}"]`, wrap), L = K.filter(k => k.c === cl[0]); $('.kbx-list', col).innerHTML = L.map(card).join(''); $('.n', col).textContent = L.length; }); bind(); }
  function bind(){
    $$('.kbx-k', wrap).forEach(el => el.onpointerdown = e => {
      if (e.button) return; const k = K.find(x => x.id === +el.dataset.id), rc = el.getBoundingClientRect(), ox = e.clientX - rc.left, oy = e.clientY - rc.top;
      let ghost = null, ph = null, moved = false;
      const move = ev => {
        if (!moved && Math.hypot(ev.clientX - e.clientX, ev.clientY - e.clientY) < 4) return;
        if (!moved){ moved = true; dragging = true; ghost = el.cloneNode(true); ghost.classList.add('ghost'); ghost.style.width = rc.width + 'px'; document.body.appendChild(ghost); el.classList.add('drag'); ph = html(`<div class="kbx-ph" style="height:${rc.height}px"></div>`); }
        ghost.style.left = ev.clientX - ox + 'px'; ghost.style.top = ev.clientY - oy + 'px';
        const col = document.elementsFromPoint(ev.clientX, ev.clientY).find(x => x.classList?.contains('kbx-c') && wrap.contains(x));
        $$('.kbx-c', wrap).forEach(x => x.classList.toggle('over', x === col));
        if (col){ const list = $('.kbx-list', col), sibs = $$('.kbx-k:not(.drag)', list); const after = sibs.find(s => { const b = s.getBoundingClientRect(); return ev.clientY < b.top + b.height / 2; }); after ? list.insertBefore(ph, after) : list.appendChild(ph); }
      };
      const up = () => { document.removeEventListener('pointermove', move); document.removeEventListener('pointerup', up);
        dragging = false; if (!moved) return; ghost.remove(); const col = ph.closest('.kbx-c');
        if (col){ const list = $('.kbx-list', col); const idx = [...list.children].filter(x => !x.classList.contains('drag')).indexOf(ph); K = K.filter(x => x !== k); k.c = col.dataset.c; if (k.c === 'done') delete k.run;
          const same = K.filter(x => x.c === k.c); const before = same[idx]; before ? K.splice(K.indexOf(before), 0, k) : K.push(k); }
        $$('.kbx-c', wrap).forEach(x => x.classList.remove('over')); paint(); const n = $(`.kbx-k[data-id="${k.id}"]`, wrap); n.animate([{ transform:'scale(1.04)' }, { transform:'none' }], { duration:350, easing:'cubic-bezier(.2,.8,.2,1)' }); };
      document.addEventListener('pointermove', move); document.addEventListener('pointerup', up);
      c.offs.push(() => { document.removeEventListener('pointermove', move); document.removeEventListener('pointerup', up); ghost?.remove(); });
    });
  }
  $$('.kbx-ch .ib', wrap).forEach(b => b.onclick = () => { const col = b.closest('.kbx-c').dataset.c; const k = { id:Date.now(), c:col, t:'New card', tag:['k','Idea'], who:['MK','var(--pl)'] }; K.push(k); paint(); const el = $(`.kbx-k[data-id="${k.id}"]`, wrap); enter(el); const t = $('.t', el); editing = true; t.contentEditable = 'true'; t.focus({ preventScroll:true }); document.getSelection().selectAllChildren(t); t.onblur = () => { editing = false; t.contentEditable = 'false'; k.t = t.textContent.trim() || 'New card'; }; t.onkeydown = e => { if (e.key === 'Enter'){ e.preventDefault(); t.blur(); } }; });
  paint();
  c.every(600, () => { if (dragging || editing) return; const k = K.find(x => x.run != null); if (!k) return; k.run = Math.min(1, k.run + .08); const el = $(`.kbx-k[data-id="${k.id}"] .kbx-pr i`, wrap); if (el) el.style.width = k.run * 100 + '%';
    if (k.run >= 1){ K = K.filter(x => x !== k); k.c = 'done'; delete k.run; K.push(k); paint(); const n = $(`.kbx-k[data-id="${k.id}"]`, wrap); enter(n);
      const nx = K.find(x => x.c === 'todo' && x.who[0] === 'DA'); if (nx){ c.later(900, function promote(){ if (dragging || editing){ c.later(300, promote); return; } K = K.filter(x => x !== nx); nx.c = 'doing'; nx.run = 0; K.splice(K.findIndex(x => x.c === 'doing'), 0, nx); paint(); enter($(`.kbx-k[data-id="${nx.id}"]`, wrap)); }); } } });
});
